for id_, s in S.items():
    folder = f"{D}/{SEC[id_.split('-')[0]]}/{id_}"
    files = sorted(p for p in glob.glob(f"{folder}/**/*", recursive=True) if os.path.isfile(p) and not p.endswith("notes.md"))
    figs = sorted(p for p in files if "/figures/" in p and os.path.basename(p).startswith(id_ + "_"))
    data_files = [p for p in files if "/figures/" not in p]
    lines = [f"# {id_}: {s['title']}", "",
             f"- **Citation:** {s['cit']}",
             f"- **url_used:** {s['url']}"]
    for o in s.get("other", []): lines.append(f"- **Also:** {o}")
    lines += [f"- **Access status:** {s['status']}",
              f"- **Headline number (from source):** {s['headline']}",
              f"- **Check vs SOURCES.md key number:** {s['check']}", "", "## Files"]
    lines += [f"- {os.path.relpath(p, folder)}" for p in data_files]
    lines += ["", "## Figures extracted"] + ([f"- {os.path.relpath(p, folder)}" for p in figs] or ["- none"])
    if s.get("extra"): lines += ["", "## Notes"] + [f"- {e}" for e in s["extra"]]
    lines += ["", "Collected 2026-10-27 with plain HTTP (UA 'gender-bias-source-collector/1.0'); scripts in scripts/scope_pay_teach_int/."]
    open(f"{folder}/notes.md", "w").write("\n".join(lines) + "\n")
    st = {"id": id_, "title": s["title"], "url_used": s["url"],
          "file_paths": [rel(p) for p in data_files] + [rel(f"{folder}/notes.md")],
          "access_status": s["status"], "figures_extracted": [rel(p) for p in figs],
          "notes": (s["check"] + ". " + s["headline"])[:600].replace("\n", " ")}
    json.dump(st, open(f"{D}/_status/{id_}.json", "w"), indent=2, ensure_ascii=False)
print(len(S), "written")
